-- ============================================================================
-- MeCart — Production SMS OTP (Twilio Verify API) hardening
-- ----------------------------------------------------------------------------
-- Adds the provider-agnostic SMS OTP ledger fields, brute-force blocking,
-- IP / device throttling and provider tracking required by the Twilio Verify
-- integration. The OTP itself is created and checked by the SMS provider
-- (Twilio Verify first) — never stored or generated by this application.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- profiles: exact columns required by the SMS OTP specification
-- ---------------------------------------------------------------------------
alter table public.profiles
  add column if not exists otp_last_sent timestamptz,
  add column if not exists last_phone_login timestamptz,
  add column if not exists failed_attempts integer not null default 0,
  add column if not exists blocked_until timestamptz,
  add column if not exists verification_provider text;

-- ---------------------------------------------------------------------------
-- phone_otp_requests: provider + device fingerprint + block tracking
-- ---------------------------------------------------------------------------
alter table public.phone_otp_requests
  add column if not exists device_id text,
  add column if not exists provider text not null default 'twilio',
  add column if not exists blocked_until timestamptz,
  add column if not exists signature_nonce text,
  add column if not exists country_code text;

alter table public.phone_otp_requests
  drop constraint if exists phone_otp_requests_purpose_check;

alter table public.phone_otp_requests
  add constraint phone_otp_requests_purpose_check
  check (purpose in (
    'login', 'registration', 'phone_verification', 'phone_change',
    'link', 'change', 'reverify'
  ));

create index if not exists idx_phone_otp_requests_ip
  on public.phone_otp_requests (client_ip, requested_at desc);

create index if not exists idx_phone_otp_requests_device
  on public.phone_otp_requests (device_id, requested_at desc);

create index if not exists idx_phone_otp_requests_active
  on public.phone_otp_requests (phone_number, purpose, expires_at desc)
  where consumed_at is null;

-- ---------------------------------------------------------------------------
-- create_phone_otp_request — throttled request creation / resend
--   * per phone: 5 requests / 30 min, 3 resends, 60s cooldown
--   * per IP: 20 requests / 60 min
--   * per device: 10 requests / 60 min
--   * blocked phones are rejected while blocked_until is in the future
-- ---------------------------------------------------------------------------
drop function if exists public.create_phone_otp_request(text, text, integer, integer);

create or replace function public.create_phone_otp_request(
  p_phone_number text,
  p_purpose text default 'login',
  p_expires_in_seconds integer default 300,
  p_max_resend integer default 3,
  p_client_ip text default null,
  p_device_id text default null,
  p_provider text default 'twilio',
  p_signature_nonce text default null,
  p_country_code text default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_request public.phone_otp_requests%rowtype;
  v_count integer;
  v_ip_count integer;
  v_device_count integer;
  v_last public.phone_otp_requests%rowtype;
  v_blocked timestamptz;
begin
  if p_phone_number is null or btrim(p_phone_number) = '' then
    raise exception 'Phone number is required';
  end if;
  if trim(p_phone_number) !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'Enter a valid E.164 phone number';
  end if;
  if p_purpose not in ('login', 'registration', 'phone_verification', 'phone_change', 'link', 'change', 'reverify') then
    raise exception 'Invalid OTP purpose';
  end if;
  if p_expires_in_seconds not between 60 and 600 then
    raise exception 'Invalid expiry';
  end if;
  if p_max_resend not between 0 and 10 then
    raise exception 'Invalid resend limit';
  end if;

  -- blocked numbers stay blocked until the block window passes
  select blocked_until into v_blocked
  from public.profiles
  where phone_number = trim(p_phone_number) and deleted_at is null
  limit 1;

  if v_blocked is not null and v_blocked > now() then
    raise exception 'Too many wrong codes. Try again later.';
  end if;

  select count(*) into v_count
  from public.phone_otp_requests
  where phone_number = trim(p_phone_number)
    and purpose = p_purpose
    and requested_at > now() - interval '30 minutes';

  if v_count >= 5 then
    raise exception 'Too many verification requests. Please try again later.';
  end if;

  if p_client_ip is not null then
    select count(*) into v_ip_count
    from public.phone_otp_requests
    where client_ip = p_client_ip
      and requested_at > now() - interval '60 minutes';

    if v_ip_count >= 20 then
      raise exception 'Too many requests from this network. Please try again later.';
    end if;
  end if;

  if p_device_id is not null then
    select count(*) into v_device_count
    from public.phone_otp_requests
    where device_id = p_device_id
      and requested_at > now() - interval '60 minutes';

    if v_device_count >= 10 then
      raise exception 'Too many requests from this device. Please try again later.';
    end if;
  end if;

  select * into v_last
  from public.phone_otp_requests
  where phone_number = trim(p_phone_number)
    and purpose = p_purpose
    and is_verified = false
    and consumed_at is null
    and expires_at > now()
  order by requested_at desc
  limit 1;

  if found then
    if v_last.blocked_until is not null and v_last.blocked_until > now() then
      raise exception 'Too many wrong codes. Try again later.';
    end if;

    if v_last.resend_count >= p_max_resend then
      raise exception 'Maximum OTP resend attempts reached. Please request a new code later.';
    end if;

    if v_last.requested_at > now() - interval '60 seconds' then
      raise exception 'Please wait % seconds before requesting another code.',
        greatest(1, ceil(extract(epoch from (v_last.requested_at + interval '60 seconds' - now())))::int);
    end if;

    update public.phone_otp_requests
    set resend_count = resend_count + 1,
        expires_at = now() + make_interval(secs => p_expires_in_seconds),
        client_ip = coalesce(p_client_ip, client_ip),
        device_id = coalesce(p_device_id, device_id),
        provider = coalesce(p_provider, provider),
        signature_nonce = coalesce(p_signature_nonce, signature_nonce),
        country_code = coalesce(p_country_code, country_code),
        last_error = null
    where id = v_last.id
    returning * into v_request;
  else
    insert into public.phone_otp_requests (
      phone_number, purpose, client_ip, device_id, provider,
      signature_nonce, country_code, expires_at
    )
    values (
      trim(p_phone_number), p_purpose, p_client_ip, p_device_id,
      coalesce(p_provider, 'twilio'), p_signature_nonce, p_country_code,
      now() + make_interval(secs => p_expires_in_seconds)
    )
    returning * into v_request;
  end if;

  update public.profiles
  set last_otp_sent_at = now(),
      otp_last_sent = now(),
      updated_at = now()
  where phone_number = trim(p_phone_number) and deleted_at is null;

  return jsonb_build_object(
    'request_id', v_request.id,
    'expires_at', v_request.expires_at,
    'resend_count', v_request.resend_count,
    'max_resend', p_max_resend,
    'cooldown_seconds', 60,
    'provider', v_request.provider
  );
end $$;

revoke all on function public.create_phone_otp_request(
  text, text, integer, integer, text, text, text, text, text
) from public, anon, authenticated;

grant execute on function public.create_phone_otp_request(
  text, text, integer, integer, text, text, text, text, text
) to service_role;

-- ---------------------------------------------------------------------------
-- verify_phone_otp_request — attempt accounting, blocking, replay safety
-- ---------------------------------------------------------------------------
drop function if exists public.verify_phone_otp_request(text, text, boolean, text);

create or replace function public.verify_phone_otp_request(
  p_phone_number text,
  p_purpose text,
  p_success boolean,
  p_error text default null,
  p_max_attempts integer default 5,
  p_block_minutes integer default 15
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_request public.phone_otp_requests%rowtype;
  v_attempts integer;
begin
  select * into v_request
  from public.phone_otp_requests
  where phone_number = trim(p_phone_number)
    and purpose = p_purpose
    and is_verified = false
    and consumed_at is null
    and expires_at > now()
  order by requested_at desc
  limit 1;

  if not found then
    raise exception 'No active verification request. Please request a new code.';
  end if;

  if v_request.blocked_until is not null and v_request.blocked_until > now() then
    return jsonb_build_object(
      'status', 'blocked',
      'request_id', v_request.id,
      'attempts', v_request.verification_attempts,
      'remaining', 0,
      'blocked_until', v_request.blocked_until
    );
  end if;

  v_attempts := v_request.verification_attempts + 1;

  if p_success then
    update public.phone_otp_requests
    set verification_attempts = v_attempts,
        is_verified = true,
        verified_at = now(),
        consumed_at = now(),
        last_error = null
    where id = v_request.id;

    update public.profiles
    set otp_attempts = 0,
        failed_attempts = 0,
        blocked_until = null,
        updated_at = now()
    where phone_number = trim(p_phone_number) and deleted_at is null;

    return jsonb_build_object(
      'status', 'verified',
      'request_id', v_request.id,
      'attempts', v_attempts,
      'remaining', greatest(0, p_max_attempts - v_attempts),
      'blocked_until', null
    );
  end if;

  if v_attempts >= p_max_attempts then
    update public.phone_otp_requests
    set verification_attempts = v_attempts,
        consumed_at = now(),
        blocked_until = now() + make_interval(mins => p_block_minutes),
        last_error = coalesce(p_error, 'max attempts reached')
    where id = v_request.id;

    update public.profiles
    set otp_attempts = otp_attempts + 1,
        failed_attempts = failed_attempts + 1,
        blocked_until = now() + make_interval(mins => p_block_minutes),
        updated_at = now()
    where phone_number = trim(p_phone_number) and deleted_at is null;

    return jsonb_build_object(
      'status', 'blocked',
      'request_id', v_request.id,
      'attempts', v_attempts,
      'remaining', 0,
      'blocked_until', now() + make_interval(mins => p_block_minutes)
    );
  end if;

  update public.phone_otp_requests
  set verification_attempts = v_attempts,
      last_error = coalesce(p_error, 'incorrect code')
  where id = v_request.id;

  update public.profiles
  set otp_attempts = otp_attempts + 1,
      failed_attempts = failed_attempts + 1,
      updated_at = now()
  where phone_number = trim(p_phone_number) and deleted_at is null;

  return jsonb_build_object(
    'status', 'failed',
    'request_id', v_request.id,
    'attempts', v_attempts,
    'remaining', greatest(0, p_max_attempts - v_attempts),
    'blocked_until', null
  );
end $$;

revoke all on function public.verify_phone_otp_request(text, text, boolean, text, integer, integer)
  from public, anon, authenticated;

grant execute on function public.verify_phone_otp_request(text, text, boolean, text, integer, integer)
  to service_role;

-- ---------------------------------------------------------------------------
-- pending_phone_otp_request — read helper (returns json null when none)
-- ---------------------------------------------------------------------------
drop function if exists public.pending_phone_otp_request(text, text);

create or replace function public.pending_phone_otp_request(
  p_phone_number text,
  p_purpose text default null
)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select to_jsonb(t)
  from public.phone_otp_requests t
  where t.phone_number = trim(p_phone_number)
    and (p_purpose is null or t.purpose = p_purpose)
    and t.expires_at > now()
    and t.consumed_at is null
    and t.is_verified = false
  order by t.requested_at desc
  limit 1
$$;

revoke all on function public.pending_phone_otp_request(text, text) from public, anon, authenticated;
grant execute on function public.pending_phone_otp_request(text, text) to service_role;

-- ---------------------------------------------------------------------------
-- expire_stale_phone_otp_requests — maintenance sweep
-- ---------------------------------------------------------------------------
create or replace function public.expire_stale_phone_otp_requests(p_limit integer default 200)
returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_count integer;
begin
  with stale as (
    select id
    from public.phone_otp_requests
    where consumed_at is null
      and is_verified = false
      and expires_at < now()
    order by expires_at asc
    limit greatest(1, least(p_limit, 1000))
  )
  update public.phone_otp_requests r
  set consumed_at = now(),
      last_error = coalesce(r.last_error, 'expired')
  from stale s
  where r.id = s.id;

  get diagnostics v_count = row_count;
  return v_count;
end $$;

revoke all on function public.expire_stale_phone_otp_requests(integer) from public, anon, authenticated;
grant execute on function public.expire_stale_phone_otp_requests(integer) to service_role;
